// static
bool StructTraits<::read_anything::mojom::ReadAnythingTheme::DataView, ::read_anything::mojom::ReadAnythingThemePtr>::Read(
    ::read_anything::mojom::ReadAnythingTheme::DataView input,
    ::read_anything::mojom::ReadAnythingThemePtr* output) {
  bool success = true;
  ::read_anything::mojom::ReadAnythingThemePtr result(::read_anything::mojom::ReadAnythingTheme::New());
  
      if (success && !input.ReadFontName(&result->font_name))
        success = false;
      if (success)
        result->font_size = input.font_size();
      if (success && !input.ReadForegroundColor(&result->foreground_color))
        success = false;
      if (success && !input.ReadBackgroundColor(&result->background_color))
        success = false;
      if (success && !input.ReadLineSpacing(&result->line_spacing))
        success = false;
      if (success && !input.ReadLetterSpacing(&result->letter_spacing))
        success = false;
  *output = std::move(result);
  return success;
}

